<?php require __DIR__.'/app/layout.php';$user=must_login();$rooms=all_rows('SELECT id,name FROM rooms WHERE status<>\'archived\' ORDER BY name');
$rows=all_rows('SELECT d.*,s.name AS room_name,u.name AS author FROM material_reports d JOIN rooms s ON s.id=d.room_id JOIN users u ON u.id=d.user_id '.(is_admin()?'':'WHERE d.user_id=?').' ORDER BY d.created_at DESC LIMIT 150',is_admin()?[]:[$user['id']]);
page_start('Déclaration de matériel','material');titlebar('Signalements','Matériel manquant','Fonctionnalité conservée de votre projet EMS original.'); ?>
<div class="row g-4"><div class="col-lg-4"><div class="panel"><div class="panel-head"><h3>Nouvelle déclaration</h3></div><form method="post" action="<?=h(url('actions.php'))?>"><?=csrf_field()?><input type="hidden" name="action" value="report_create"><div class="mb-3"><label class="form-label">Salle *</label><select class="form-select" name="room_id" required><option value="">Sélectionner…</option><?php foreach($rooms as $r):?><option value="<?=h($r['id'])?>"><?=h($r['name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Matériel manquant *</label><input class="form-control" maxlength="190" name="missing_item" required placeholder="Ex. Câble HDMI"></div><div class="mb-4"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="4" maxlength="3000"></textarea></div><?php submit_button('Envoyer la déclaration');?></form></div></div><div class="col-lg-8"><div class="panel"><div class="panel-head"><h3>Déclarations enregistrées</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Salle</th><th>Matériel</th><th>Description</th><th>Déclaré par</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['room_name'])?></td><td class="fw-semibold"><?=h($r['missing_item'])?></td><td><?=h(textclip((string)$r['description'],75))?></td><td><?=h($r['author'])?></td><td><?=h($r['created_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty-state">Aucun signalement.</td></tr><?php endif;?></tbody></table></div></div></div></div>
<?php page_end();?>
